#include "asset_protocol.h"
static uint16_t rd16(const uint8_t*p){return (uint16_t)((p[0]<<8)|p[1]);} static uint32_t rd32(const uint8_t*p){return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}
static void wr16(uint8_t*p,uint16_t v){p[0]=(uint8_t)(v>>8);p[1]=(uint8_t)v;} static void wr32(uint8_t*p,uint32_t v){p[0]=(uint8_t)(v>>24);p[1]=(uint8_t)(v>>16);p[2]=(uint8_t)(v>>8);p[3]=(uint8_t)v;}
uint32_t asst_crc32(const void*d,uint32_t n){uint32_t c=~0u;const uint8_t*p=d;while(n--){c^=*p++;for(int i=0;i<8;i++)c=(c>>1)^(UINT32_C(0xedb88320)&-(int)(c&1));}return ~c;}
int asst_encode(uint8_t o[32],const asst_header*h){if(!o||!h||h->magic!=ASST_MAGIC||h->version!=1||h->payload_len>ASST_MAX_PAYLOAD||h->flags&~3u)return -1;wr32(o,h->magic);wr16(o+4,h->version);wr16(o+6,h->type);wr32(o+8,h->session);wr32(o+12,h->asset_id);wr32(o+16,h->offset);wr16(o+20,h->payload_len);wr16(o+22,h->flags);wr32(o+24,h->sequence);wr32(o+28,h->payload_crc32);return 0;}
int asst_decode(asst_header*h,const uint8_t i[32]){if(!h||!i)return -1;h->magic=rd32(i);h->version=rd16(i+4);h->type=rd16(i+6);h->session=rd32(i+8);h->asset_id=rd32(i+12);h->offset=rd32(i+16);h->payload_len=rd16(i+20);h->flags=rd16(i+22);h->sequence=rd32(i+24);h->payload_crc32=rd32(i+28);if(h->magic!=ASST_MAGIC||h->version!=1||h->type<ASST_GET||h->type>ASST_ERROR||h->payload_len>ASST_MAX_PAYLOAD||(h->offset&3u)||h->flags&~3u)return -1;if(h->type==ASST_DATA&&h->payload_len==0)return -1;return 0;}
